"""Runs the app's archive/search SQL (generated by QueryHarness.kt) against an SQLite copy
of the Room schema, with FTS4 'simple' tokenizer, and checks the results."""
import json, sqlite3, sys

d = json.load(open(sys.argv[1], encoding="utf-8"))
db = sqlite3.connect(":memory:")
db.executescript("""
CREATE TABLE items (id TEXT PRIMARY KEY NOT NULL, ftsDocId INTEGER NOT NULL, version INTEGER NOT NULL, jurisdiction TEXT NOT NULL,
  docType TEXT NOT NULL, lawId TEXT, lawNumber INTEGER, lawYearGc INTEGER, lawYearEc INTEGER, titleEn TEXT, titleAm TEXT,
  summaryEn TEXT, summaryAm TEXT, issuer TEXT, initiator TEXT, status TEXT, verifiedStatus TEXT, reportedStatus TEXT,
  verification TEXT NOT NULL, sourceCount INTEGER NOT NULL, hasOfficialSource INTEGER NOT NULL, topics TEXT NOT NULL, amends TEXT,
  eventDate INTEGER, statusDate INTEGER, firstSeenAt INTEGER, updatedAt INTEGER, relevance REAL NOT NULL, sourcesJson TEXT NOT NULL);
CREATE VIRTUAL TABLE item_fts USING FTS4(titles TEXT NOT NULL, summary TEXT NOT NULL, lawId TEXT NOT NULL, meta TEXT NOT NULL, body TEXT NOT NULL, tokenize=simple);
CREATE TABLE user_state (itemId TEXT PRIMARY KEY NOT NULL, read INTEGER NOT NULL, bookmarked INTEGER NOT NULL, bookmarkedAt INTEGER, note TEXT);
CREATE TABLE tags (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, name TEXT NOT NULL);
CREATE TABLE item_tags (itemId TEXT NOT NULL, tagId INTEGER NOT NULL, PRIMARY KEY(itemId, tagId));
""")
for it in d["items"]:
    db.execute("INSERT INTO items VALUES (?,?,1,?,?,NULL,NULL,NULL,NULL,?,NULL,NULL,NULL,?,NULL,?,?,?,?,3,1,?,NULL,?,?,0,0,0,'[]')",
               (it["id"], it["doc"], it["jur"], it["docType"], it["id"], it["issuer"], it["status"], it["verifiedStatus"],
                it["status"], it["verification"], it["topics"], it["day"], it["day"]))
    db.execute("INSERT INTO item_fts(rowid,titles,summary,lawId,meta,body) VALUES (?,?,?,?,?,?)", (it["doc"], *it["fts"]))
db.execute("INSERT INTO user_state VALUES ('dig',1,1,NULL,NULL)")
db.execute("INSERT INTO user_state VALUES ('foi',1,0,NULL,NULL)")
db.execute("INSERT INTO tags(name) VALUES ('client X')")
db.execute("INSERT INTO item_tags VALUES ('efda',1)")
expected = {
    "default": ["tax", "dig", "efda", "foi"],
    "amharic_info": ["dig", "foi"],          # መረጃ: FOI title, and the digital item's topic label "ዲጂታል፣ መረጃና ቴሌኮም"
    "amharic_variant": ["foi"], "law_ec_year": ["foi"], "law_gc_year": ["foi"], "issuer_text_am": ["efda"],
    "draft_bills": ["dig"], "imminent": ["tax"], "verified_30d": ["dig"], "topic_tax_or_health": ["tax", "efda"],
    "intl": ["au"], "all_bookmarked": ["dig"], "tagged": ["efda"], "issuer_efda": ["efda"], "unread": ["tax", "efda"],
}
failed = 0
for q in d["queries"]:
    rows = [r[0] for r in db.execute(q["sql"], q["args"]).fetchall()]
    ok = rows == expected[q["name"]]
    failed += not ok
    print("PASS" if ok else "FAIL", q["name"], rows, "" if ok else f"expected {expected[q['name']]}")
print(f"{len(d['queries']) - failed} passed, {failed} failed")
sys.exit(1 if failed else 0)
